      "claim": "The framework creates a monitorability tax that shifts the burden of proof from developers to regulators, immunizing corporations from the consequences of system failure.",
      "targets": []
    },
    {
      "claim": "The continuous management model is a strategic normalization of the loss of human agency, masking the impossibility of meaningful control in high-speed combat.",
      "targets": []
    },
    {
      "claim": "The framework functions as constitutionalism as corporate rhetoric, bypassing democratic mandates to place lethal force under the governance of private technical standards.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Legal liability is the only effective incentive for corporations to prioritize public safety over internal efficiency.",
      "if_wrong": "I would support industry-led self-regulation as a viable path to safety."
    },
    {
      "assumption": "Meaningful human control over lethal force is a non-delegable moral and political duty.",
      "if_wrong": "I would accept the delegation of lethal decision-making to autonomous systems provided they meet technical accuracy benchmarks."
    }
  ]
}

